// ---------- piezas propias de este video ----------
const Qr: React.FC<{x: number; y: number; size: number; seed?: number; logo?: string}> = ({x, y, size, seed = 1, logo}) => {
  const n = 11, c = size / n;
  const fin3 = (i: number, j: number) => (i < 7 && j < 7) || (i > n - 8 && j < 7) || (i < 7 && j > n - 8);
  const cells: React.ReactNode[] = [];
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    if (fin3(i, j)) continue;
    if (h(seed * 97 + i * 13 + j * 7) > 0.48) cells.push(<rect key={i * 20 + j} x={-size / 2 + i * c} y={-size / 2 + j * c} width={c + 0.5} height={c + 0.5} fill="#10131a" />);
  }
  const finder = (fx: number, fy: number, k: number) => (
    <g key={k} transform={`translate(${-size / 2 + fx * c} ${-size / 2 + fy * c})`}>
      <rect width={7 * c} height={7 * c} fill="#10131a" /><rect x={c} y={c} width={5 * c} height={5 * c} fill="#e9edf2" /><rect x={2 * c} y={2 * c} width={3 * c} height={3 * c} fill="#10131a" />
    </g>
  );
  return (
    <g transform={`translate(${x} ${y})`}>
      <rect x={-size / 2 - c * 0.6} y={-size / 2 - c * 0.6} width={size + c * 1.2} height={size + c * 1.2} fill="#e9edf2" />
      {cells}{finder(0, 0, 1)}{finder(n - 7, 0, 2)}{finder(0, n - 7, 3)}
      {logo && <g><circle r={c * 1.5} fill="#e9edf2" /><circle r={c * 1.15} fill={logo} /><text y={c * 0.5} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={c * 1.5} fill="#fff">P</text></g>}
    </g>
  );
};

// calcomania falsa: lift 0..1 levanta la esquina inferior derecha
