  const S = size / 2 + 14, L = 24 + lift * 300;
  const id = 'cal' + Math.round(size);
  return (
    <g transform={`translate(${x} ${y}) rotate(${r})`}>
      <defs><clipPath id={id}><polygon points={`${-S},${-S} ${S},${-S} ${S},${S - L} ${S - L},${S} ${-S},${S}`} /></clipPath></defs>
      <g clipPath={`url(#${id})`}>
        <rect x={-S + 5} y={-S + 8} width={2 * S} height={2 * S} fill="rgba(0,0,0,0.35)" />
        <rect x={-S} y={-S} width={2 * S} height={2 * S} fill="#e9edf2" />
        <Qr x={0} y={0} size={size - 20} seed={2} logo="#d63b3b" />
        <polygon points={`${S},${S - L} ${S - L},${S} ${S - L},${S - L}`} fill="rgba(255,255,255,0)" />
      </g>
      <polygon points={`${S},${S - L} ${S - L},${S} ${S - L},${S - L}`} fill="#c9ced6" stroke="#8d95a3" strokeWidth={3} />
      <polygon points={`${S},${S - L} ${S - L},${S} ${S - L / 2},${S - L / 2}`} fill="rgba(255,255,255,0.55)" />
    </g>
  );
};

