// ================= SITIO A: parquimetro y calcomania (E1) =================
const A_CAM = [P(0, 540, 830, 1.0), P(ESCANEAS, 540, 830, 1.25)];
const SitioA: React.FC = () => {
  const {s, spr} = useS();
  const k = ro(s, PEGO - 0.15, PEGO + 0.15);
  const wp = [[960, 360, 24, 1.5], [760, 640, 12, 1.35], [610, 760, 4, 1.18], [540, 830, 0, 1.0]];
  const aprox = ro(s, 0, PEGO - 0.15);
  const seg = aprox * 3, si = Math.min(2, Math.floor(seg)), f = seg - si;
  const lerp = (a: number, b: number) => a + (b - a) * eio(f);
  const ax = lerp(wp[si][0], wp[si + 1][0]), ay = lerp(wp[si][1], wp[si + 1][1]), ar = lerp(wp[si][2], wp[si + 1][2]), ak = lerp(wp[si][3], wp[si + 1][3]);
  const pegado = s >= PEGO - 0.15;
  const hand = 1 - eio(ro(s, PEGO + 0.3, PEGO + 0.9));
  const alisa = ro(s, PEGO, PEGO + 0.7);
  const lift = 0.07 * ro(s, IGUAL, IGUAL + 0.8);
  const golpeP = Math.max(0, golpe(s, PEGO, 16, 8));
  return (
    <AbsoluteFill>
      <Camara paradas={A_CAM}>
        <Textura tipo="fibra" base="radial-gradient(circle at 50% 45%, #1d3358 0%, #0e1a33 65%, #060b18 100%)" linea="rgba(120,170,255,0.22)" luz="rgba(120,170,255,0.14)" semilla={12} />
        <Brillo x={540} y={820} r={520} color="rgba(130,180,255,0.30)" />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
          <Parq lcd="PAGA AQUÍ" parp={0.6 + 0.4 * Math.abs(Math.sin(s * 3))} />
          <Qr x={540} y={830} size={250} seed={1} logo="#d63b3b" />
          {pegado ? <Calco x={540} y={830} size={250} lift={lift} r={0} /> : <g transform={`translate(0 0)`}><Calco x={ax} y={ay + 0} size={250 * ak} lift={0} r={ar} /></g>}
          {pegado && <rect x={330} y={680 + alisa * 300} width={420} height={8} fill="rgba(255,255,255,0.35)" opacity={1 - alisa} />}
          <g transform={`translate(${pegado ? 760 + (1 - hand) * 500 : ax + 150} ${(pegado ? 1100 : ay + 220) + golpeP * 10 + (pegado ? (1 - hand) * 600 : 0)}) rotate(${pegado ? -25 : ar - 150}) scale(0.8)`}>
            <Mano x={0} y={0} guante dedo={false} />
